"""Tests for AST import extraction."""

from __future__ import annotations

import ast
from pathlib import Path

import pytest

from depcycle.parsing.imports import ASTParser, _ImportVisitor


def test_import_visitor_direct_nodes() -> None:
    """Test import visitor behavior for directly constructed AST nodes."""
    visitor = _ImportVisitor()

    bare_node = ast.ImportFrom(
        module=None,
        level=0,
        names=[ast.alias(name="foo")],
    )
    visitor.visit(bare_node)

    assert visitor.imports == set()

    visitor = _ImportVisitor()

    star_relative = ast.ImportFrom(
        module=None,
        level=1,
        names=[
            ast.alias(name="*"),
            ast.alias(name="localmod"),
        ],
    )
    visitor.visit(star_relative)

    assert visitor.imports == {".localmod"}


def test_import_visitor_import_statement() -> None:
    """Test normal import statements and aliases."""
    visitor = _ImportVisitor()

    node = ast.Import(
        names=[
            ast.alias(name="os"),
            ast.alias(name="sys", asname="system"),
            ast.alias(name="os.path"),
        ]
    )

    visitor.visit(node)

    assert visitor.imports == {
        "os",
        "sys",
        "os.path",
    }


def test_import_visitor_from_statement() -> None:
    """Test from-import module extraction."""
    visitor = _ImportVisitor()

    nodes = [
        ast.ImportFrom(module="os", level=0, names=[ast.alias(name="path")]),
        ast.ImportFrom(module="os.path", level=0, names=[ast.alias(name="join")]),
        ast.ImportFrom(module="sub", level=1, names=[ast.alias(name="helper")]),
        ast.ImportFrom(module="models", level=2, names=[ast.alias(name="User")]),
    ]

    for node in nodes:
        visitor.visit(node)

    assert visitor.imports == {
        "os",
        "os.path",
        ".sub",
        "..models",
    }


def test_future_imports_are_ignored() -> None:
    """Test that __future__ imports are excluded."""
    visitor = _ImportVisitor()

    node = ast.ImportFrom(
        module="__future__",
        level=0,
        names=[ast.alias(name="annotations")],
    )

    visitor.visit(node)

    assert visitor.imports == set()


def test_relative_bare_imports() -> None:
    """Test bare relative imports such as from . import module."""
    visitor = _ImportVisitor()

    node = ast.ImportFrom(
        module=None,
        level=1,
        names=[
            ast.alias(name="local_a"),
            ast.alias(name="local_b"),
            ast.alias(name="*"),
        ],
    )

    visitor.visit(node)

    assert visitor.imports == {
        ".local_a",
        ".local_b",
    }


def test_get_imports_from_file_valid(tmp_path: Path) -> None:
    """Test extracting supported import styles from valid source."""
    code = """\
from __future__ import annotations

import os
import sys as system
import os.path
import os, json
from path_lib import Path
from . import local_sub
from . import *
from ..parent import helper
from .TimeAccount import TimeAccount
"""
    file_path = tmp_path / "sample.py"
    file_path.write_text(code, encoding="utf-8")

    imports = ASTParser.get_imports_from_file(file_path)

    assert imports == {
        "os",
        "sys",
        "os.path",
        "json",
        "path_lib",
        ".local_sub",
        "..parent",
        ".TimeAccount",
    }


def test_get_imports_from_file_nonexistent(tmp_path: Path) -> None:
    """Test that missing files raise FileNotFoundError."""
    with pytest.raises(FileNotFoundError):
        ASTParser.get_imports_from_file(tmp_path / "nonexistent.py")


def test_get_imports_from_file_invalid_syntax(tmp_path: Path) -> None:
    """Test that invalid Python raises SyntaxError."""
    file_path = tmp_path / "invalid.py"
    file_path.write_text(
        "def class broken_syntax(:",
        encoding="utf-8",
    )

    with pytest.raises(SyntaxError):
        ASTParser.get_imports_from_file(file_path)


def test_get_imports_from_file_unicode_error(tmp_path: Path) -> None:
    """Test that invalid UTF-8 raises UnicodeDecodeError."""
    file_path = tmp_path / "non_utf8.py"
    file_path.write_bytes(b"\x80\x81\x82\xff")

    with pytest.raises(UnicodeDecodeError):
        ASTParser.get_imports_from_file(file_path)
